insert into public.export_policies (id, country, region_code, name, kind, true_up, note, source_url, verified_on, verification) values
  ('de-eeg-teileinspeisung', 'DE', null, 'EEG-Einspeisevergütung: Überschusseinspeisung (Teileinspeisung), bis 10 kW', 'feed_in', null, 'Eigenverbrauch zuerst, der Überschuss wird nach EEG vergütet. Gilt für Anlagen, die vom 1. August bis 31. Dezember 2026 in Betrieb gehen, 20 Jahre lang (section 25 EEG). Ohne intelligentes Messsystem (Smart Meter) muss neue Anlagen die Einspeiseleistung auf 60 Prozent der installierten Leistung begrenzen (section 9 Abs. 2 EEG); dieser Ertragsverlust und der Wegfall der Vergütung bei negativen Strompreisen sind in der Rechnung NICHT berücksichtigt.', 'https://www.bundesnetzagentur.de/DE/Fachthemen/ElektrizitaetundGas/ErneuerbareEnergien/EEG_Foerderung/start.html', '2026-11-22', 'agent_sourced'),
  ('de-eeg-volleinspeisung', 'DE', null, 'EEG-Einspeisevergütung: Volleinspeisung, bis 10 kW', 'gross_metering', null, 'Der gesamte Solarstrom wird eingespeist und zum höheren Volleinspeisesatz vergütet; Ihren Strom kaufen Sie weiter zum normalen Preis, die Stromrechnung sinkt nicht. Gilt für Anlagen, die vom 1. August bis 31. Dezember 2026 in Betrieb gehen, 20 Jahre lang (section 25 EEG). Die Begrenzung auf 60 Prozent ohne Smart Meter und der Wegfall der Vergütung bei negativen Preisen sind NICHT berücksichtigt.', 'https://www.bundesnetzagentur.de/DE/Fachthemen/ElektrizitaetundGas/ErneuerbareEnergien/EEG_Foerderung/start.html', '2026-11-22', 'agent_sourced');
insert into public.export_policy_rates (policy_id, valid_from, valid_to, years_from, years_to, rate_low, rate_likely, rate_high, note, source_url, verified_on, verification) values
  ('de-eeg-teileinspeisung', '2026-08-01', '2026-12-31', 1, null, 0.077, 0.077, 0.077, '7,70 ct/kWh Teileinspeisung bis 10 kW, Inbetriebnahme 1.8.-31.12.2026 (section 21 i.V.m. sections 48, 49, 53 EEG 2023), Bundesnetzagentur. Held flat over the 20-year payment term.', 'https://www.bundesnetzagentur.de/DE/Fachthemen/ElektrizitaetundGas/ErneuerbareEnergien/EEG_Foerderung/start.html', '2026-11-22', 'agent_sourced'),
  ('de-eeg-volleinspeisung', '2026-08-01', '2026-12-31', 1, null, 0.1222, 0.1222, 0.1222, '12,22 ct/kWh Volleinspeisung bis 10 kW, Inbetriebnahme 1.8.-31.12.2026, Bundesnetzagentur. Held flat over the 20-year payment term.', 'https://www.bundesnetzagentur.de/DE/Fachthemen/ElektrizitaetundGas/ErneuerbareEnergien/EEG_Foerderung/start.html', '2026-11-22', 'agent_sourced');
insert into public.vat_rates (id, country, applies_to, rate, valid_from, valid_to, note, source_url, publisher, verified_on, verification) values
  ('de-solar-zero-rate', 'DE', 'solar', 0, '2023-01-01', null, 'Nullsteuersatz auf Lieferung und Installation von Photovoltaikanlagen auf oder nahe Privatwohnungen, bis 30 kW(peak). Seit 1. Januar 2023 (Verbraucherzentrale bestätigt: seit dem 1.1.2023 keine Umsatzsteuer auf private PV-Anlagen).', 'https://www.gesetze-im-internet.de/ustg_1980/__12.html', 'UStG section 12 Abs. 3', '2026-11-22', 'agent_sourced'),
  ('de-battery-zero-rate', 'DE', 'battery', 0, '2023-01-01', null, 'Nullsteuersatz auch für Speicher, die den mit Solarmodulen erzeugten Strom speichern (section 12 Abs. 3 Nr. 1 und 4 UStG).', 'https://www.gesetze-im-internet.de/ustg_1980/__12.html', 'UStG section 12 Abs. 3', '2026-11-22', 'agent_sourced');
insert into public.cost_ranges (country, region_code, item, low, likely, high, unit, note, source_url, verified_on, verification, includes_tax) values
  ('DE', 'DE', 'installed_cost_per_watt', 1.41, 1.71, 2.09, 'EUR per watt DC (Verbraucherzentrale EUR per kWp / 1,000)', 'Built only from the published Verbraucherzentrale NRW size-band AVERAGES for PV up to 10 kWp (Stand 3 Nov 2026; offers Jan 2025 - Aug 2026; n = 71 PV offers over all sizes): low = the >9-10 kWp band, EUR 1,410/kWp; high = the 4-6 kWp band, EUR 2,090/kWp; likely = the unweighted mean of the four published band averages up to 10 kWp (2,090 + 1,820 + 1,520 + 1,410) / 4 = EUR 1,710/kWp (a derived figure: the page gives no per-band counts or medians). Larger systems cost less per kWp. Excludes battery. Prices are net; PV carries 0% VAT (public.vat_rates). Not a quote.', 'https://www.verbraucherzentrale.de/wissen/energie/erneuerbare-energien/was-kostet-eine-photovoltaikanlage-49155', '2026-11-22', 'agent_sourced', false),
  ('DE', 'DE', 'battery_installed_cost', 3600, 4100, 5100, 'EUR per battery system (10 kWh)', 'One battery = 10 kWh of capacity. Built only from the published Verbraucherzentrale NRW storage averages (Stand 3 Nov 2026; n = 70 battery offers, Jan 2025 - Aug 2026, installed together with PV): likely = the >8-10 kWh band, EUR 410/kWh x 10 kWh = EUR 4,100; low = the cheapest band, >12-16 kWh at EUR 360/kWh x 10 = EUR 3,600; high = the dearest band, 4-6 kWh at EUR 510/kWh x 10 = EUR 5,100. The page does not state the VAT basis for storage; storage carries 0% VAT (public.vat_rates), so tax-inclusive and ex-tax are the same here. Not a quote.', 'https://www.verbraucherzentrale.de/wissen/energie/erneuerbare-energien/was-kostet-eine-photovoltaikanlage-49155', '2026-11-22', 'agent_sourced', false);
insert into public.model_assumptions (key, country, region_code, value, unit, rationale) values
  ('pvwatts_system_loss_pct', 'DE', null, '{"none": 14, "some": 20, "heavy": 30}'::jsonb, 'percent', 'PVGIS system losses (the key keeps its legacy name). 14% is the PVGIS default system loss and what every yield figure on the site uses; 20% (some shade) and 30% (heavy shade) are product choices that step the loss up for partial and heavy shade. Not sourced.'),
  ('target_offset', 'DE', null, '{"low": 0.8, "high": 1.0}'::jsonb, 'fraction of annual usage', 'Product choice: size the system to cover 80% to 100% of estimated annual usage, which gives the low and high ends of the suggested size range. Not sourced.'),
  ('system_size_cap_kw', 'DE', null, '{"value": 10}'::jsonb, 'kW DC', 'Product choice: the Verbraucherzentrale NRW cost data used for pricing is shown per size band, and the EEG rates used here are those for systems up to 10 kW, so the suggested size is capped at 10 kW rather than priced outside the data. Not sourced.'),
  ('min_system_size_kw', 'DE', null, '{"value": 1.5}'::jsonb, 'kW DC', 'Product choice: below this a payback figure is not meaningful for a rooftop installation, so the calculator warns instead. Not sourced.'),
  ('max_monthly_bill', 'DE', null, '{"value": 1000}'::jsonb, 'EUR per month', 'Input sanity limit for the monthly bill field, so a typing slip (an extra zero) is caught. Not sourced.'),
  ('panel_degradation_per_year', 'DE', null, '{"value": 0.005}'::jsonb, 'fraction per year', 'Product choice: 0.5% less output each year, a conventional planning figure for crystalline silicon panels (same as the GB calculator). Not sourced.'),
  ('analysis_years', 'DE', null, '{"value": 20}'::jsonb, 'years', 'Product choice: a 20-year projection with no discounting, equal to the EEG payment term (section 25 EEG: 20 years). There is no sourced export price for years 21 to 25, so the model stops where the sourced rate stops. Inverter and battery replacement are not modelled.'),
  ('missing_range_spread', 'DE', null, '{"value": 0.15}'::jsonb, 'fraction', 'Product choice: where a source gives a likely value but no bounds, low and high are likely -/+ 15% and the result says they are estimated. Placeholder until bounds are sourced. Same as GB.'),
  ('annual_rate_escalation', 'DE', null, '{"low": 0, "likely": 0.02, "high": 0.04}'::jsonb, 'fraction per year', 'Product choice: electricity prices flat (low), rising 2% a year (likely) or 4% a year (high). Not a forecast and not sourced; the same planning range as the GB calculator.'),
  ('self_consumption_share', 'DE', null, '{"solar_only": {"low": 0.3, "likely": 0.4, "high": 0.55}, "solar_plus_1_battery": {"low": 0.55, "likely": 0.7, "high": 0.85}, "solar_plus_2_batteries": {"low": 0.7, "likely": 0.85, "high": 0.95}}'::jsonb, 'fraction of solar output used at home', 'NO PRIMARY SOURCE FOUND (an open item for the owner: a missing fact, not a null column, so the generated docs/TODO-VERIFY.md does not list it). The same deliberately wide product-choice ranges as the GB calculator: how much solar output is used at home rather than exported depends on when the household is at home. Replace with a measured source (for example the HTW Berlin Stromspeicher-Inspektion or a national study) when one is verified.'),
  ('battery_usable_kwh', 'DE', null, '{"value": 10}'::jsonb, 'kWh', 'Product choice: one battery is modelled as 10 kWh of capacity, the Verbraucherzentrale NRW storage band >8-10 kWh used for the cost row. The study states capacity, not usable energy. Not a recommendation.'),
  ('orientation_yield_factor', 'DE', null, '{"east_west": {"low": 0.772, "likely": 0.786, "high": 0.799}, "north": {"low": 0.509, "likely": 0.514, "high": 0.52}}'::jsonb, 'fraction of equator-facing yield', 'Derived from 12 PVGIS 5.3 runs (1 kWp, 35 degree tilt, 14% losses, PVGIS-SARAH3), retrieved 2026-11-22, for Hamburg, Berlin and Muenchen: yield facing east, west or north divided by yield facing south (aspect 0). East/west ratios: Hamburg 0.799 / 0.783, Berlin 0.795 / 0.772, Muenchen 0.784 / 0.782 (low = smallest, high = largest, likely = mean of the six = 0.786). North: 0.520, 0.509, 0.512 (likely = mean = 0.514). Source: https://re.jrc.ec.europa.eu/api/v5_3/PVcalc (lat/lon of each city, peakpower=1, loss=14, angle=35, aspect=0/90/-90/180).'),
  ('install_horizon', 'DE', null, '{"until": "2026-12-31"}'::jsonb, 'ISO date', 'Product choice: install dates are offered only up to 31 Dec 2026, the last day of the sourced EEG feed-in rates (Bundesnetzagentur). The successor rule (EEG-Novelle 2027, Drs. 21/7867) had not passed on 2026-11-22, so no 2027 rate exists to use; the calculator does not guess one. Move this date when the law is passed and rates are sourced.');
