insert into public.utilities (id, display_order, name, country, region_code, metering_type, rate_schedule, rate_type, fixed_monthly_charge, fixed_charge_note, minimum_bill_basis, rate_note, source_url, verified_on, verification, avg_rate_likely, avg_rate_unit, avg_rate_note, avg_rate_source_url, avg_rate_verified_on, avg_rate_verification) values
  ('au-ausgrid', 10, 'Ausgrid network (NSW)', 'AU', 'AU', 'feed_in', 'AER Default Market Offer 2026-27, residential flat rate tariff cap, incl. GST', 'flat', round(166.2289 * 365 / 12 / 100, 2), '166.2289 cents per day x 365 / 12 / 100 = AUD per month (supply charge, incl. GST).', 'not_applicable', 'Ausgrid network (NSW). DMO caps apply to standing offers; your own retailer plan will differ. Read from an archived copy of the AER final determination (the AER site blocks bots).', 'https://www.aer.gov.au/system/files/2026-05/AER%20-%20Final%20determination%20-%20Default%20market%20offer%202026%E2%80%9327.pdf', '2026-11-22', 'agent_sourced', round(33.1372 / 100, 6), 'AUD per kWh', '33.1372 cents per kWh usage charge, DMO 2026-27 residential flat rate tariff cap, incl. GST, 1 Jul 2026 to 30 Jun 2027. A cap on standing offers, not a market offer price.', 'https://www.aer.gov.au/system/files/2026-05/AER%20-%20Final%20determination%20-%20Default%20market%20offer%202026%E2%80%9327.pdf', '2026-11-22', 'agent_sourced'),
  ('au-endeavour-energy', 11, 'Endeavour Energy network (NSW)', 'AU', 'AU', 'feed_in', 'AER Default Market Offer 2026-27, residential flat rate tariff cap, incl. GST', 'flat', round(185.1350 * 365 / 12 / 100, 2), '185.1350 cents per day x 365 / 12 / 100 = AUD per month (supply charge, incl. GST).', 'not_applicable', 'Endeavour Energy network (NSW). DMO caps apply to standing offers; your own retailer plan will differ. Read from an archived copy of the AER final determination (the AER site blocks bots).', 'https://www.aer.gov.au/system/files/2026-05/AER%20-%20Final%20determination%20-%20Default%20market%20offer%202026%E2%80%9327.pdf', '2026-11-22', 'agent_sourced', round(33.7273 / 100, 6), 'AUD per kWh', '33.7273 cents per kWh usage charge, DMO 2026-27 residential flat rate tariff cap, incl. GST, 1 Jul 2026 to 30 Jun 2027. A cap on standing offers, not a market offer price.', 'https://www.aer.gov.au/system/files/2026-05/AER%20-%20Final%20determination%20-%20Default%20market%20offer%202026%E2%80%9327.pdf', '2026-11-22', 'agent_sourced'),
  ('au-essential-energy', 12, 'Essential Energy network (NSW)', 'AU', 'AU', 'feed_in', 'AER Default Market Offer 2026-27, residential flat rate tariff cap, incl. GST', 'flat', round(272.2168 * 365 / 12 / 100, 2), '272.2168 cents per day x 365 / 12 / 100 = AUD per month (supply charge, incl. GST).', 'not_applicable', 'Essential Energy network (NSW). DMO caps apply to standing offers; your own retailer plan will differ. Read from an archived copy of the AER final determination (the AER site blocks bots).', 'https://www.aer.gov.au/system/files/2026-05/AER%20-%20Final%20determination%20-%20Default%20market%20offer%202026%E2%80%9327.pdf', '2026-11-22', 'agent_sourced', round(35.0054 / 100, 6), 'AUD per kWh', '35.0054 cents per kWh usage charge, DMO 2026-27 residential flat rate tariff cap, incl. GST, 1 Jul 2026 to 30 Jun 2027. A cap on standing offers, not a market offer price.', 'https://www.aer.gov.au/system/files/2026-05/AER%20-%20Final%20determination%20-%20Default%20market%20offer%202026%E2%80%9327.pdf', '2026-11-22', 'agent_sourced'),
  ('au-energex', 13, 'Energex network (south-east Queensland)', 'AU', 'AU', 'feed_in', 'AER Default Market Offer 2026-27, residential flat rate tariff cap, incl. GST', 'flat', round(192.0159 * 365 / 12 / 100, 2), '192.0159 cents per day x 365 / 12 / 100 = AUD per month (supply charge, incl. GST).', 'not_applicable', 'Energex network (south-east Queensland). DMO caps apply to standing offers; your own retailer plan will differ. Read from an archived copy of the AER final determination (the AER site blocks bots).', 'https://www.aer.gov.au/system/files/2026-05/AER%20-%20Final%20determination%20-%20Default%20market%20offer%202026%E2%80%9327.pdf', '2026-11-22', 'agent_sourced', round(27.9744 / 100, 6), 'AUD per kWh', '27.9744 cents per kWh usage charge, DMO 2026-27 residential flat rate tariff cap, incl. GST, 1 Jul 2026 to 30 Jun 2027. A cap on standing offers, not a market offer price.', 'https://www.aer.gov.au/system/files/2026-05/AER%20-%20Final%20determination%20-%20Default%20market%20offer%202026%E2%80%9327.pdf', '2026-11-22', 'agent_sourced'),
  ('au-sa-power-networks', 14, 'SA Power Networks (South Australia)', 'AU', 'AU', 'feed_in', 'AER Default Market Offer 2026-27, residential flat rate tariff cap, incl. GST', 'flat', round(180.0512 * 365 / 12 / 100, 2), '180.0512 cents per day x 365 / 12 / 100 = AUD per month (supply charge, incl. GST).', 'not_applicable', 'SA Power Networks (South Australia). DMO caps apply to standing offers; your own retailer plan will differ. Read from an archived copy of the AER final determination (the AER site blocks bots).', 'https://www.aer.gov.au/system/files/2026-05/AER%20-%20Final%20determination%20-%20Default%20market%20offer%202026%E2%80%9327.pdf', '2026-11-22', 'agent_sourced', round(41.9103 / 100, 6), 'AUD per kWh', '41.9103 cents per kWh usage charge, DMO 2026-27 residential flat rate tariff cap, incl. GST, 1 Jul 2026 to 30 Jun 2027. A cap on standing offers, not a market offer price.', 'https://www.aer.gov.au/system/files/2026-05/AER%20-%20Final%20determination%20-%20Default%20market%20offer%202026%E2%80%9327.pdf', '2026-11-22', 'agent_sourced'),
  ('au-synergy-a1', 15, 'Synergy, Residential A1 (Western Australia)', 'AU', 'AU', 'feed_in', 'Energy Policy WA, Residential Tariff A1, 2026-27, incl. GST', 'flat', round(119.24 * 365 / 12 / 100, 2), '119.24 cents (AUD 1.1924) per day x 365 / 12 / 100 = AUD per month (supply charge, incl. GST).', 'not_applicable', 'Regulated Synergy Residential A1 tariff. Horizon Power (regional WA) charges the same A1 usage rate but is not a separate choice here.', 'https://www.wa.gov.au/organisation/energy-policy-wa/household-electricity-pricing', '2026-11-22', 'agent_sourced', round(33.2621 / 100, 6), 'AUD per kWh', '33.2621 cents per kWh usage charge and 119.24 cents (AUD 1.1924) per day supply charge, Residential A1, 1 Jul 2026 to 30 Jun 2027, incl. GST, Energy Policy WA.', 'https://www.wa.gov.au/organisation/energy-policy-wa/household-electricity-pricing', '2026-11-22', 'agent_sourced'),
  ('au-jacana-standard', 16, 'Jacana Energy, Standard Residential (Northern Territory)', 'AU', 'AU', 'feed_in', 'Jacana Energy Standard Residential tariff, 2026-27, incl. GST', 'flat', round(62.45 * 365 / 12 / 100, 2), '62.45 cents per day x 365 / 12 / 100 = AUD per month (supply charge, incl. GST).', 'not_applicable', 'Jacana Energy Standard Residential tariff.', 'https://jacanaenergy.com.au/your-home/pricing-and-plans/residential-pricing-and-tariffs', '2026-11-22', 'agent_sourced', round(31.6788 / 100, 6), 'AUD per kWh', '31.6788 cents per kWh usage charge and 62.45 cents per day supply charge, Standard Residential, 1 Jul 2026 to 30 Jun 2027, incl. GST, Jacana Energy.', 'https://jacanaenergy.com.au/your-home/pricing-and-plans/residential-pricing-and-tariffs', '2026-11-22', 'agent_sourced');
insert into public.export_policies (id, country, region_code, name, kind, true_up, note, source_url, verified_on, verification) values
  ('au-nsw-ipart-benchmark', 'AU', null, 'New South Wales: IPART all-day benchmark (2026-27)', 'feed_in', null, 'IPART benchmark range 3.4 to 6.5 cents per kWh for 2026-27, the range retailers are expected to price against (not a guaranteed rate). The likely value is the midpoint of the published range. Time-of-day benchmarks are higher in the evening (about 17 to 33 cents depending on the network) but are not modelled.', 'https://www.ipart.nsw.gov.au/sites/default/files/cm9_documents/Fact-Sheet-All-day-solar-feed-in-tariff-benchmark-tariff-2026-27.PDF', '2026-11-22', 'agent_sourced'),
  ('au-qld-regional-qca', 'AU', null, 'Regional Queensland: regulated feed-in tariff (2026-27)', 'feed_in', null, 'Queensland Competition Authority regulated solar feed-in tariff for regional Queensland, 6.006 cents per kWh for 2026-27 (down 31%). South-east Queensland retailers set their own rates.', 'https://www.qca.org.au/wp-content/uploads/2025/12/solar-fit-fact-sheet-june-2026.pdf', '2026-11-22', 'agent_sourced'),
  ('au-vic-minimum', 'AU', null, 'Victoria: legal minimum (no minimum feed-in tariff)', 'feed_in', null, 'The Essential Services Commission has set no minimum feed-in tariff since 1 July 2025, so the legal floor is 0 cents per kWh. This is the worst case: retailers choose their own rates and many pay more.', 'https://www.esc.vic.gov.au/electricity-and-gas/electricity-and-gas-tariffs-and-benchmarks/minimum-feed-tariff', '2026-11-22', 'agent_sourced'),
  ('au-wa-synergy-debs', 'AU', null, 'Western Australia, Synergy: buyback outside 3 pm to 9 pm', 'feed_in', null, 'Synergy DEBS pays 2 cents per kWh for exports outside 3 pm to 9 pm (midday solar exports fall here) and 10 cents from 3 pm to 9 pm; only the 2 cent rate is modelled. Rates shown are those published as at 1 July 2024: the WA page was last updated in December 2024 and 2026-27 rates are not confirmed.', 'https://www.wa.gov.au/organisation/energy-policy-wa/energy-buyback-schemes', '2026-11-22', 'agent_sourced'),
  ('au-tas-aurora-regulated', 'AU', null, 'Tasmania: Aurora regulated feed-in tariff (2026-27)', 'feed_in', null, 'Regulated feed-in tariff of 9.276 cents per kWh for 2026-27 (Aurora Energy, from the Tasmanian Economic Regulator decision).', 'https://www.auroraenergy.com.au/residential/payments/tasmanian-energy-prices', '2026-11-22', 'agent_sourced'),
  ('au-nt-jacana-anytime', 'AU', null, 'Northern Territory, Jacana: feed-in at any time (2026-27)', 'feed_in', null, 'Jacana Energy pays 9.33 cents per kWh at any time. A higher 18.66 cents "Super FiT" applies from 3 pm to 9 pm with a smart meter and is not modelled.', 'https://jacanaenergy.com.au/your-home/pricing-and-plans/residential-pricing-and-tariffs', '2026-11-22', 'agent_sourced');
insert into public.export_policy_rates (policy_id, valid_from, valid_to, years_from, years_to, rate_low, rate_likely, rate_high, note, source_url, verified_on, verification) values
  ('au-nsw-ipart-benchmark', '2026-07-01', '2027-06-30', 1, null, 0.034, 0.0495, 0.065, 'IPART all-day benchmark 3.4 to 6.5 cents per kWh, 2026-27; likely = (3.4 + 6.5) / 2 = 4.95 (derived midpoint). Held flat over time.', 'https://www.ipart.nsw.gov.au/sites/default/files/cm9_documents/Fact-Sheet-All-day-solar-feed-in-tariff-benchmark-tariff-2026-27.PDF', '2026-11-22', 'agent_sourced'),
  ('au-qld-regional-qca', '2026-07-01', '2027-06-30', 1, null, 0.06006, 0.06006, 0.06006, '6.006 cents per kWh, QCA regulated solar feed-in tariff, 1 Jul 2026 to 30 Jun 2027. Held flat over time.', 'https://www.qca.org.au/wp-content/uploads/2025/12/solar-fit-fact-sheet-june-2026.pdf', '2026-11-22', 'agent_sourced'),
  ('au-vic-minimum', '2025-07-01', null, 1, null, 0, 0, 0, '0 cents per kWh: no minimum feed-in tariff since 1 July 2025 (Essential Services Commission).', 'https://www.esc.vic.gov.au/electricity-and-gas/electricity-and-gas-tariffs-and-benchmarks/minimum-feed-tariff', '2026-11-22', 'agent_sourced'),
  ('au-wa-synergy-debs', '2024-07-01', null, 1, null, 0.02, 0.02, 0.02, '2 cents per kWh Synergy DEBS outside 3 pm to 9 pm, as at 1 July 2024 (Energy Policy WA). 2026-27 rate unconfirmed.', 'https://www.wa.gov.au/organisation/energy-policy-wa/energy-buyback-schemes', '2026-11-22', 'agent_sourced'),
  ('au-tas-aurora-regulated', '2026-07-01', '2027-06-30', 1, null, 0.09276, 0.09276, 0.09276, '9.276 cents per kWh regulated feed-in tariff, 1 Jul 2026 to 30 Jun 2027 (Aurora Energy).', 'https://www.auroraenergy.com.au/residential/payments/tasmanian-energy-prices', '2026-11-22', 'agent_sourced'),
  ('au-nt-jacana-anytime', '2026-07-01', '2027-06-30', 1, null, 0.0933, 0.0933, 0.0933, '9.33 cents per kWh anytime feed-in, 1 Jul 2026 to 30 Jun 2027 (Jacana Energy).', 'https://jacanaenergy.com.au/your-home/pricing-and-plans/residential-pricing-and-tariffs', '2026-11-22', 'agent_sourced');
insert into public.incentives (id, country, region_code, name, administrator, applies_to, incentive_type, amount_type, amount_low, amount_likely, amount_high, cap_amount, cap_percent_of_cost, max_kw, max_kwh, taxable, excludes_export_kind, status, status_as_of, effective_from, effective_to, eligibility_note, note, source_url, verified_on, verification) values
  ('au-chbp-2026-05-to-12', 'AU', null, 'Cheaper Home Batteries Program (STC factor 6.8)', 'Clean Energy Regulator', 'battery', 'rebate', 'per_kwh_storage', round(39.62 * 6.8 * 0.9, 2), round(39.62 * 6.8, 2), round(40 * 6.8, 2), null, null, null, null, null, null, 'open', '2026-11-22', '2026-05-01', '2026-12-31', 'Batteries certified for compliance from 1 May 2026, installed with solar, on the Clean Energy Council approved list; size tiers 100% / 60% / 15% of the factor for 0-14 / >14-28 / >28-50 usable kWh.', 'AUD per usable kWh = STC factor 6.8 x STC price: likely 39.62 x 6.8 = 269.42 (spot, CER, 15 May 2026), high 40 x 6.8 = 272.00 (Clearing House price), low = likely x 0.9 (10% admin fee, CHOICE, SECONDARY). Paid as a point-of-sale discount. State rebates and VPP incentives are not included.', 'https://www.legislation.gov.au/F2026L00093/asmade/2026-02-09/text/original/pdf', '2026-11-22', 'agent_sourced'),
  ('au-chbp-2027-01-to-06', 'AU', null, 'Cheaper Home Batteries Program (STC factor 5.7)', 'Clean Energy Regulator', 'battery', 'rebate', 'per_kwh_storage', round(39.62 * 5.7 * 0.9, 2), round(39.62 * 5.7, 2), round(40 * 5.7, 2), null, null, null, null, null, null, 'open', '2026-11-22', '2027-01-01', '2027-06-30', 'Batteries certified for compliance from 1 January 2027; same size tiers.', 'AUD per usable kWh = STC factor 5.7 x STC price: likely 39.62 x 5.7 = 225.83 (spot, CER, 15 May 2026), high 40 x 5.7 = 228.00, low = likely x 0.9 (10% admin fee, CHOICE, SECONDARY). The step down from 6.8 to 5.7 on 1 January 2027 is the Clean Energy Regulator schedule (reg 20(8)); the STC price in 2027 is not known.', 'https://www.legislation.gov.au/F2026L00093/asmade/2026-02-09/text/original/pdf', '2026-11-22', 'agent_sourced');
insert into public.cost_ranges (country, region_code, item, low, likely, high, unit, note, source_url, verified_on, verification, includes_tax) values
  ('AU', 'AU', 'installed_cost_per_watt', 0.9, 1, 1.5, 'AUD per watt DC (after the point-of-sale STC discount, incl. GST)', 'SECONDARY SOURCE (SolarQuotes, a lead-generation site, last updated 12 Oct 2026): typical fully installed prices buyers reported paying, 5 kW AUD 5,000-7,500; 6.6 kW 6,000-9,000; 8 kW 7,500-11,000; 10 kW 9,000-12,000. low = 10 kW low end 9,000 / 10,000 W = 0.90; likely = the page''s rule of thumb of about AUD 1,000 per kW = 1.00; high = 5 kW high end 7,500 / 5,000 W = 1.50. The page does not state whether the STC discount is deducted or whether GST is included; treated as the price the buyer pays (after STCs, incl. GST). The 2026 STC discount shrinks every 1 January (deeming period 5 years in 2026, 4 in 2027), which is not modelled. Not a quote.', 'https://www.solarquotes.com.au/panels/cost/', '2026-11-22', 'agent_sourced', true),
  ('AU', 'AU', 'battery_installed_cost', 9720, 11720, 13720, 'AUD per battery system (10 kWh usable), BEFORE the federal rebate, incl. GST', 'SECONDARY SOURCE, DERIVED: CHOICE (prices from SolarQuotes partners) lists 10 kWh storage at AUD 7,000-11,000 installed after the federal rebate, and prints the 2026 rebate as AUD 272 per kWh (6.8 STC x about AUD 40). The calculator deducts the rebate itself, so the row is the before-rebate price: 7,000 + 2,720 = 9,720 (low); 11,000 + 2,720 = 13,720 (high); likely = midpoint 11,720 (derived, not published). Includes installation and GST. Real quotes vary with brand, inverter and installer. Not a quote.', 'https://www.choice.com.au/home-and-living/energy-and-water/energy-saving-products/articles/solar-home-battery-rebate', '2026-11-22', 'agent_sourced', true);
insert into public.model_assumptions (key, country, region_code, value, unit, rationale) values
  ('pvwatts_system_loss_pct', 'AU', null, '{"none": 14, "some": 20, "heavy": 30}'::jsonb, 'percent', 'PVGIS system losses (the key keeps its legacy name). 14% is the PVGIS default system loss and what every yield figure on the site uses; 20% (some shade) and 30% (heavy shade) are product choices that step the loss up for partial and heavy shade. Not sourced.'),
  ('target_offset', 'AU', null, '{"low": 0.8, "high": 1.0}'::jsonb, 'fraction of annual usage', 'Product choice: size the system to cover 80% to 100% of estimated annual usage, which gives the low and high ends of the suggested size range. Not sourced.'),
  ('system_size_cap_kw', 'AU', null, '{"value": 10}'::jsonb, 'kW DC', 'Product choice: the SolarQuotes price table used for pricing runs from 3 kW to 13 kW and the 5-10 kW rows set the range, so the suggested size is capped at 10 kW rather than priced outside the data. Not sourced.'),
  ('min_system_size_kw', 'AU', null, '{"value": 1.5}'::jsonb, 'kW DC', 'Product choice: below this a payback figure is not meaningful for a rooftop installation, so the calculator warns instead. Not sourced.'),
  ('max_monthly_bill', 'AU', null, '{"value": 1500}'::jsonb, 'AUD per month', 'Input sanity limit for the monthly bill field, so a typing slip (an extra zero) is caught. Not sourced.'),
  ('panel_degradation_per_year', 'AU', null, '{"value": 0.005}'::jsonb, 'fraction per year', 'Product choice: 0.5% less output each year, a conventional planning figure for crystalline silicon panels (same as the GB calculator). Not sourced.'),
  ('analysis_years', 'AU', null, '{"value": 25}'::jsonb, 'years', 'Product choice: a 25-year projection with no discounting, the same horizon as the US and GB calculators. Inverter and battery replacement are not modelled.'),
  ('missing_range_spread', 'AU', null, '{"value": 0.15}'::jsonb, 'fraction', 'Product choice: where a source gives a likely value but no bounds, low and high are likely -/+ 15% and the result says they are estimated. Placeholder until bounds are sourced. Same as GB.'),
  ('annual_rate_escalation', 'AU', null, '{"low": 0, "likely": 0.02, "high": 0.04}'::jsonb, 'fraction per year', 'Product choice: electricity prices flat (low), rising 2% a year (likely) or 4% a year (high). Not a forecast and not sourced; the same planning range as the GB calculator.'),
  ('self_consumption_share', 'AU', null, '{"solar_only": {"low": 0.3, "likely": 0.4, "high": 0.55}, "solar_plus_1_battery": {"low": 0.55, "likely": 0.7, "high": 0.85}, "solar_plus_2_batteries": {"low": 0.7, "likely": 0.85, "high": 0.95}}'::jsonb, 'fraction of solar output used at home', 'NO PRIMARY SOURCE FOUND (an open item for the owner: a missing fact, not a null column, so the generated docs/TODO-VERIFY.md does not list it). The same deliberately wide product-choice ranges as the GB calculator: how much solar output is used at home rather than exported depends on when the household is at home. Replace with a measured source (for example the HTW Berlin Stromspeicher-Inspektion or a national study) when one is verified.'),
  ('battery_usable_kwh', 'AU', null, '{"value": 10}'::jsonb, 'kWh', 'Product choice: one battery is modelled as 10 kWh of usable capacity, the size of the CHOICE price row used for the battery cost (10 kWh, AUD 7,000-11,000 after rebate). It sits inside the first rebate tier (0-14 kWh). Not a recommendation.'),
  ('orientation_yield_factor', 'AU', null, '{"east_west": {"low": 0.742, "likely": 0.801, "high": 0.837}, "north": {"low": 0.5, "likely": 0.528, "high": 0.567}}'::jsonb, 'fraction of equator-facing yield', 'Derived from 12 PVGIS 5.3 runs (1 kWp, 35 degree tilt, 14% losses, PVGIS-ERA5), retrieved 2026-11-22, for Sydney, Melbourne and Brisbane: yield facing east, west or the pole divided by yield facing the equator (north, aspect 180). THE KEY "north" HOLDS THE POLE-FACING (SOUTH-FACING) RATIO FOR AUSTRALIA, because the keys are shared with northern-hemisphere markets where the equator-facing side is south. East/west ratios: Sydney 0.814 / 0.742, Melbourne 0.801 / 0.787, Brisbane 0.837 / 0.825 (low = smallest, high = largest, likely = mean of the six = 0.801). Pole-facing: 0.500, 0.516, 0.567 (likely = mean = 0.528). Source: https://re.jrc.ec.europa.eu/api/v5_3/PVcalc (lat/lon of each city, peakpower=1, loss=14, angle=35, aspect=180/90/-90/0).'),
  ('install_horizon', 'AU', null, '{"until": "2027-06-30"}'::jsonb, 'ISO date', 'Product choice: install dates are offered only up to 30 Jun 2027. The federal battery rebate factors (6.8, then 5.7) and the regulated feed-in rates are sourced for that window; the 2027-28 feed-in rates are not published yet. The STC price after 2026 is not known either (the dollar value uses the mid-May 2026 spot price).');
